              aria-haspopup="dialog"
              title="Open the full note"
              onClick$={() => {
                openFullThread({ kind: "note", id: note.id });
                onClose$();
              }}
            >
              <ExpandIcon />
            </button>
            <button
              type="button"
              onClick$={onClose$}
              class="persona-note__tool focus-ring"
              aria-label="Close note"
              title="Close"
            >
              <CloseIcon />
            </button>
          </div>
