   286	/* ── Rewrite anchor selection (deterministic edit targets) ─────── */
   287	
   288	function pickAnchorSentences(
   289	  text: string,
   290	  personaIds: string[],
   291	): Record<string, string> {
   292	  const sentences: string[] = [];
   293	  for (const paragraph of text.split(/\n+/)) {
   294	    const matches = paragraph.match(/[^.!?]+[.!?]+(?=\s|$)/g) ?? [];
   295	    for (const raw of matches) {
   296	      const sentence = raw.trim();
   297	      if (sentence.split(/\s+/).length >= 6) sentences.push(sentence);
   298	    }
   299	  }
   300	  if (sentences.length === 0) return {};
   301	
   302	  const used = new Set<number>();
   303	  const take = (start: number): string | undefined => {
   304	    for (let step = 0; step < sentences.length; step++) {
   305	      const i = (start + step) % sentences.length;
   306	      if (!used.has(i)) {
   307	        used.add(i);
   308	        return sentences[i];
   309	      }
   310	    }
   311	    return undefined;
   312	  };
   313	
   314	  const longest = sentences.reduce(
   315	    (best, s, i) => (s.length > sentences[best].length ? i : best),
   316	    0,
   317	  );
   318	  const evidence = sentences.findIndex((s) =>
   319	    /\d|percent|study|studies|research|according to|evidence/i.test(s),
   320	  );
   321	  const claim = sentences.findIndex((s) =>
   322	    /\b(must|should|clearly|obviously|always|never|every|all of|no one|undeniabl)/i.test(
   323	      s,
   324	    ),
   325	  );
   326	
   327	  const preferred: Record<string, number> = {
   328	    reader: 0,
   329	    editor: longest,
   330	    devil: claim >= 0 ? claim : Math.floor(sentences.length / 2),
   331	    scholar: evidence >= 0 ? evidence : Math.floor((sentences.length * 2) / 3),
   332	    angel: Math.floor(sentences.length / 3),
   333	  };
   334	
   335	  const result: Record<string, string> = {};
   336	  for (const id of personaIds) {
   337	    if (id in preferred) {
   338	      const s = take(preferred[id]);
   339	      if (s) result[id] = s;
   340	    }
   341	  }
   342	  let cursor = 0;
   343	  for (const id of personaIds) {
   344	    if (result[id] !== undefined || id in preferred) continue;
   345	    const s = take(cursor++ % sentences.length);
   346	    if (s) result[id] = s;
   347	  }
   348	  return result;
   349	}
