      test = unwrap(test);
      if (test.type === "UnaryExpression" && test.operator === "!")
        return provesNonempty(test.argument, !truthy, array);
      if (test.type === "LogicalExpression") {
        if (
          (test.operator === "&&" && truthy) ||
          (test.operator === "||" && !truthy)
