    { code: "const Layout = function(props) { return <main>{props.children}</main>; }; const ui = <Layout><select /></Layout>;", errors: [error] },
    { code: "const Layout = (props) => <main>{props.children}</main>; const ui = <Layout><div contentEditable /></Layout>;", errors: [error] },
    { code: "const Layout = (props) => <main>{props.children}</main>; const Alias = Layout; const ui = <Alias><input /></Alias>;", errors: [error] },
    { code: "const Form = () => <input />; const ui = <Form></Form>;", errors: [error] },
  ],
});

// Minimal proposed workaround, not a claim that application code was fixed.
export const after = (personas, streamingNotes, replyDraft) => {
  const cards = personas.filter((persona) => streamingNotes[persona.id]).map((persona) => <article key={persona.id} />);
  return <div>{cards.length ? cards : null}<dialog key="note-sheet"><textarea value={replyDraft} /></dialog></div>;
};

