        const typed = local ? null : typedDefinition(name);
        if (!local && !typed) return;
        if (!editable(node) && !(local ? editable(local.body) : typedEditable(typed.body))) return;
        context.report({ node, messageId: "plainWrapper", data: { name: source.getText(name) } });
