import plugin from "/home/diogenes/Projects/apps/twyne/packages/eslint-plugin-qwik-guards/src/index.js";

const require = createRequire("/home/diogenes/Projects/apps/twyne/package.json");
const { ESLint } = require("eslint");
const tseslint = require("typescript-eslint");
const targets = JSON.parse(readFileSync("/tmp/qwik-cross-project-audit/targets.json", "utf8"));
const project = targets[Number(process.argv[2])];
if (!project) throw new Error("Invalid target index");
let files = [];
try {
  files = execFileSync("rg", ["--files", "-g", "*.tsx", "-g", "*.jsx",
    "-g", "!**/node_modules/**", "-g", "!**/vendor/**", "-g", "!**/dist/**",
    "-g", "!**/server/**", "-g", "!**/launch-videos/**", "-g", "!**/social-preview-video/**",
    "-g", "!**/target/**", project.path], { encoding: "utf8" }).trim().split("\n").filter(Boolean).sort();
} catch (error) { if (error.status !== 1) throw error; }

function linter(typed) {
  return new ESLint({
    cwd: project.path, overrideConfigFile: true, ignore: false, cache: false,
    overrideConfig: [{
      ...plugin.configs.recommended,
      languageOptions: {
        parser: tseslint.parser,
        parserOptions: { ecmaFeatures: { jsx: true }, projectService: typed, tsconfigRootDir: project.path },
      },
    }],
  });
}
const typed = linter(true), syntaxOnly = linter(false);
const results = [];
for (const file of files) {
  const code = readFileSync(file, "utf8");
  let [result] = await typed.lintText(code, { filePath: file });
  let typedFailure = null;
  if (result.fatalErrorCount) {
    typedFailure = result.messages.map(m => m.message).join("\n");
    [result] = await syntaxOnly.lintText(code, { filePath: file });
  }
  results.push({
    file, relative: relative(project.path, file), typed: !typedFailure, typedFailure,
    sha256: createHash("sha256").update(code).digest("hex"),
    parserErrors: result.fatalErrorCount,
    warnings: result.messages.map(m => ({
      ruleId: m.ruleId, severity: m.severity, line: m.line, column: m.column,
      endLine: m.endLine, message: m.message,
      snippet: code.split("\n").slice(Math.max(0, m.line - 2), Math.min(code.split("\n").length, m.line + 4)).join("\n"),
    })),
  });
}
const counts = {};
for (const result of results) for (const warning of result.warnings)
  counts[warning.ruleId ?? "parser/other"] = (counts[warning.ruleId ?? "parser/other"] ?? 0) + 1;
const summary = { path: project.path, installed: project.installed, files: files.length,
  typedFiles: results.filter(r => r.typed).length, syntaxOnlyFiles: results.filter(r => !r.typed).length,
  parserErrors: results.reduce((n,r) => n + r.parserErrors, 0), counts };
writeFileSync(join("/tmp/qwik-cross-project-audit", `result-${process.argv[2]}.json`), JSON.stringify({ summary, results }, null, 2) + "\n");
console.log(JSON.stringify(summary));

