            <Link
              href={`/app/projects/${p._id}`}
              class="cad-soft p-4 flex flex-col gap-1 hover:border-[var(--border-strong)] block"
            >
              <span class="font-medium">{p.name}</span>
              {p.instructions ? (
                <span class="text-xs text-[var(--fg-muted)] line-clamp-2">
                  {p.instructions}
                </span>
              ) : (
                <span class="text-xs text-[var(--fg-faint)]">
                  No instructions yet
                </span>
              )}
            </Link>
          </li>
        ))}
