const STAGES = ["Measure", "Draft prompts", "Baste (QD)", "Fit (judge)", "Cut"];

/** Rough stage from the server's log lines, checked from the latest stage back. */
function stageOf(job: Job | null): number {
  if (!job) return -1;
  if (job.status === "completed") return STAGES.length;
  const text = job.logs.join("\n").toLowerCase();
  if (/^done:/m.test(text)) return 4;
  if (/generating final assets/.test(text)) return 3;
  if (/candidate \d|generation \d|qd archive|qd evolution/.test(text)) return 2;
  if (/prompt|generating|asset types|ui kit/.test(text)) return 1;
  return 0;
}

